css:
@page {
    size: A4;
    margin: 1cm;
}

.print-container {
    font-size: 12px;
}

.receipt-header {
    text-align: center;
    margin-bottom: 20px;
}

.receipt-header h2 {
    margin-bottom: 5px;
}

.section {
    margin-top: 20px;
}

.section h3 {
    border-bottom: 1px solid #000;
    padding-bottom: 5px;
}

.details-table,
.parts-table,
.totals {
    width: 100%;
    border-collapse: collapse;
}

.details-table td,
.parts-table th,
.parts-table td,
.totals td {
    border: 1px solid #ccc;
    padding: 6px;
}

.parts-table th {
    font-weight: bold;
}

.totals {
    margin-top: 20px;
}

.totals td:last-child {
    text-align: right;
}

.final-amount td {
    font-size: 20px;
    font-weight: bold;
}

.urgent-banner {
    text-align: center;
    font-size: 22px;
    font-weight: bold;
    border: 2px solid #000;
    padding: 8px;
    margin: 15px 0;
}

.page-break {
    page-break-before: always;
}

@media print {
    .no-print {
        display: none !important;
    }
}
